      // --- invalid QR text / missing fields -> error -> Try Again -> scanning ---
      for (const [kind, qrObj, expect] of [['invalid-json', 'not-json-synthetic', /Invalid QR code/], ['missing-fields', { tokenId: PAYLOAD.tokenId, rowVersion: PAYLOAD.rowVersion }, /missing required data/]]) {
